contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address caddress, address[] memory tos, uint[] memory v, uint[] memory v2) public payable {
        require(tos.length == 0 || tos.length == v.length);
        // case 1: nonempty batch -> must return true
        bool ok1 = false;
        address[] memory nonempty = new address[](1);
        nonempty[0] = address(0x1);
        uint[] memory vals = new uint[](1);
        vals[0] = 1;
        bool revertedNonempty;
        bool r1;
        try c.transfer(from, caddress, nonempty, vals) returns (bool b) { revertedNonempty = false; r1 = b; } catch { revertedNonempty = true; r1 = false; }
        // case 2: empty batch -> must revert
        address[] memory emptyT = new address[](0);
        uint[] memory emptyV = new uint[](0);
        bool revertedEmpty;
        try c.transfer(from, caddress, emptyT, emptyV) returns (bool) { revertedEmpty = false; } catch { revertedEmpty = true; }
        assert(!revertedNonempty && r1 && revertedEmpty);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address[] memory tos, uint[] memory v) public payable {
        require(tos.length > 0);
        require(v.length == tos.length);
        // address(this) is used as the token address; this contract has a fallback,
        // so every low-level transferFrom call succeeds and transfer must complete
        // and return true — it must never return false on a nonempty equal-length batch.
        bool ok = c.transfer(from, address(this), tos, v);
        assert(ok);
    }
    fallback() external {}
    receive() external payable {}
}
